arguments.new_str:
using Microsoft.ML;
using Microsoft.ML.Data;

var builder = WebApplication.CreateBuilder(args);

// Register the pooled prediction engine (thread-safe for web apps)
var mlContext = new MLContext(seed: 42);
var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");
var dataView = mlContext.Data.LoadFromTextFile<ChurnInput>(dataPath, hasHeader: true, separatorChar: ',');

var split = mlContext.Data.TrainTestSplit(dataView, testFraction: 0.2);

var pipeline = mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(ChurnInput.Region))
    .Append(mlContext.Transforms.Concatenate("Features", nameof(ChurnInput.Age), nameof(ChurnInput.Income),
        "RegionEncoded", nameof(ChurnInput.PurchaseHistory)))
    .Append(mlContext.Transforms.NormalizeMinMax("Features"))
    .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
        labelColumnName: nameof(ChurnInput.Churned),
        featureColumnName: "Features"));

var model = pipeline.Fit(split.TrainSet);

// Evaluate on test set
var predictions = model.Transform(split.TestSet);
var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: nameof(ChurnInput.Churned));
Console.WriteLine($"Model trained — AUC: {metrics.AreaUnderRocCurve:F4}, Accuracy: {metrics.Accuracy:F4}, F1: {metrics.F1Score:F4}");

builder.Services.AddPredictionEnginePool<ChurnInput, ChurnOutput>()
    .FromUri(modelName: "ChurnModel",
        uri: "", // unused — we load from the trained model below
        period: TimeSpan.Zero);

var app = builder.Build();

// Save and reload model via the pool
var modelPath = Path.Combine(AppContext.BaseDirectory, "ChurnModel.zip");
mlContext.Model.Save(model, dataView.Schema, modelPath);

builder.Services.AddPredictionEnginePool<ChurnInput, ChurnOutput>()
    .FromFile(modelName: "ChurnModel", filePath: modelPath, watchForChanges: false);

app.MapGet("/", () => "Churn Predictor API — POST to /predict");

app.MapPost("/predict", (ChurnInput input, Microsoft.Extensions.ML.PredictionEnginePool<ChurnInput, ChurnOutput> pool) =>
{
    var prediction = pool.GetPrediction("ChurnModel", input);
    return Results.Ok(new
    {
        willChurn = prediction.PredictedLabel,
        probability = prediction.Probability,
        score = prediction.Score
    });
});

app.Run();

public class ChurnInput
{
    [LoadColumn(0)]
    public float Age { get; set; }

    [LoadColumn(1)]
    public float Income { get; set; }

    [LoadColumn(2)]
    public string Region { get; set; } = "";

    [LoadColumn(3)]
    public float PurchaseHistory { get; set; }

    [LoadColumn(4), ColumnName("Label")]
    public bool Churned { get; set; }
}

public class ChurnOutput
{
    [ColumnName("PredictedLabel")]
    public bool PredictedLabel { get; set; }

    public float Probability { get; set; }

    public float Score { get; set; }
}

